"""Guard layer: wraps any delegate agent so a must-have is always ASKED for in the term sheet and an
open thread is never abandoned while something sensible is left to try.

Why: practice runs lost cases with no deal because sheets were snapped (by `complete_offer`) onto
an option that breaks a must-have, and the agents then walked away. `satisfy_must_haves` fixes the
sheets; `GuardedAgent` turns a delegate's walk-away (or crash) into an accept of a safe standing
sheet, or into one more counter at the supplier's own price with the must-haves satisfied.
"""

import logging

from .cost import OPS, complete_offer, must_haves_ok, total_cost
from .docs import standard_terms
from .play import ENDED, closing_move, latest, live_threads, moves_left, standing

log = logging.getLogger("arena")

MAX_COUNTERS = 2  # guard counters per thread and case
ASK_QUOTE = "Could you please send us your quote?"
ASK_BODY = "We can proceed at your price if the terms below work for you; please confirm."


def _fits(m, value):
    try:
        return value is not None and OPS[m["op"]](value, m["value"])
    except TypeError:
        return False


def _must_have_value(case, m, current):
    """A value for the must-have's field that satisfies it, or `current` when none can."""
    op, bound = m["op"], m["value"]
    options = [o for o in (case.get("term_options") or {}).get(m["field"]) or [] if o is not None]
    if options:
        ok = [o for o in options if _fits(m, o)]
        if not ok:
            return current
        if op in ("<=", "<"):
            return max(ok)
        if op in (">=", ">"):
            return min(ok)
        if op == "!=":
            return current if _fits(m, current) else ok[0]
        return bound
    if op in ("<=", ">=", "=="):
        return bound
    if op == "!=":
        return current if _fits(m, current) else (bound + 1 if isinstance(bound, int | float) else current)
    step = 1 if isinstance(bound, int) else 0.01
    return bound - step if op == "<" else bound + step


def satisfy_must_haves(case, terms, standard=None):
    """A copy of `terms` with every must-have on a negotiable field satisfied, completed to a valid
    sheet. Must-haves on fields we cannot negotiate are left alone."""
    result = dict(terms)
    for m in case["buyer"].get("must_haves", []):
        if m["field"] in case["negotiable"] and not _fits(m, result.get(m["field"])):
            result[m["field"]] = _must_have_value(case, m, result.get(m["field"]))
    result = complete_offer(case, result)
    if not must_haves_ok(case, result, standard):
        log.debug("guard: must-haves still fail after fixing %s", result)
    return result


def fix_sheets(case, sheets, standard=None):
    """`satisfy_must_haves` on each sheet; exact duplicates dropped; at most 3 kept."""
    out = []
    for s in sheets:
        fixed = {"terms": satisfy_must_haves(case, s.get("terms") or {}, standard)}
        if fixed not in out:
            out.append(fixed)
    return out[:3]


def _changes(old, new):
    return ", ".join(f"{k} {old.get(k)} -> {v}" for k, v in new.items() if old.get(k) != v)


def _text(sid, body, sheets=None):
    msg = {"subject": "Our proposal", "body": body}
    if sheets:
        msg["term_sheets"] = sheets
    return {"supplier_id": sid, "message": msg}


class GuardedAgent:
    def __init__(self, delegate, log_name="arena"):
        self.delegate = delegate
        self.log = logging.getLogger(log_name)
        self._case_id = None
        self._tried = {}

    def _reset(self, case):
        if case.get("case_id") != self._case_id:
            self._case_id, self._tried = case.get("case_id"), {}

    def decide(self, case, threads):
        self._reset(case)
        error = False
        try:
            decision = self.delegate.decide(case, threads)
        except Exception:
            log.exception("%s guard: delegate crashed", self._case_id)
            decision, error = None, True
        msg = (decision or {}).get("message") or {}
        action = msg.get("action") or {}
        if decision and action.get("type") == "accept":
            return decision
        sid = (decision or {}).get("supplier_id")
        if decision and msg.get("term_sheets"):
            sheets = self._fix(case, threads, sid, msg["term_sheets"])
            if sheets:
                return self._last_move(case, threads, {**decision, "message": {**msg, "term_sheets": sheets}})
        elif decision and not action:
            return self._last_move(case, threads, decision)  # a text-only message
        reason = "delegate crashed" if error else "delegate wanted to walk" if action else "no usable sheet"
        return self._keep_going(case, threads, sid, reason)

    def _fix(self, case, threads, sid, sheets):
        std = standard_terms(threads[sid]) if sid in threads else {}
        fixed = fix_sheets(case, sheets, std)
        for old, new in zip(sheets, fixed, strict=True):
            if (c := _changes(old.get("terms") or {}, new["terms"])) and old.get("terms") != new["terms"]:
                self.log.info("%s guard: fixed sheet %s (must-have)", self._case_id, c)
        return fixed

    def _last_move(self, case, threads, decision):
        """Rule e: on our last allowed message, a price push the supplier will refuse is replaced."""
        sid = decision["supplier_id"]
        if sid not in threads:
            return decision
        left = moves_left(case, threads[sid])
        if left > 1:
            return decision
        if left < 1:
            self.log.info("%s guard: closing move (no messages left on %s)", self._case_id, sid)
            return closing_move(case, threads)
        sheets = decision["message"].get("term_sheets") or []
        offered = {
            t.get("unit_price")
            for m in threads[sid] if m.get("from") != "buyer"
            for s in m.get("term_sheets") or [] for t in [s.get("terms") or {}]
        }
        prices = [s["terms"].get("unit_price") for s in sheets]
        if not sheets or min((p for p in prices if p is not None), default=None) in offered:
            return decision
        close = closing_move(case, threads)
        if close["message"]["action"]["type"] == "accept":
            self.log.info("%s guard: accept on last move (a lower counter would be refused)", self._case_id)
            return close
        counter = self._counter(case, threads, sid)
        if counter:
            self.log.info("%s guard: must-have counter at their price on last move", self._case_id)
            return counter
        return decision

    def _counter(self, case, threads, sid):
        events = threads[sid]
        _, terms = standing(events)
        if terms.get("unit_price") is None:
            body = _text(sid, ASK_QUOTE)
        else:
            sheet = satisfy_must_haves(case, dict(terms), standard_terms(events))
            body = _text(sid, ASK_BODY, [{"terms": sheet}])
        key = (self._case_id, sid)
        self._tried[key] = self._tried.get(key, 0) + 1
        return body

    def _eligible(self, case, threads, sid):
        events = threads[sid]
        status, left = latest(events).get("status"), moves_left(case, events)
        n = self._tried.get((self._case_id, sid), 0)
        cap = 1 if status == "final_offer" else MAX_COUNTERS
        return status not in ENDED and left >= 1 and n < cap

    def _keep_going(self, case, threads, preferred, reason):
        """Rule d: never walk while something sensible is left."""
        close = closing_move(case, threads)
        if close["message"]["action"]["type"] == "accept":
            self.log.info("%s guard: accept a safe standing sheet (%s)", self._case_id, reason)
            return close
        live = [s for s in live_threads(threads) if self._eligible(case, threads, s)]

        def cost(s):
            sheet_id, terms = standing(threads[s])
            try:
                return total_cost(case, terms, standard_terms(threads[s])) if terms.get("unit_price") else float("inf")
            except Exception:
                return float("inf")

        order = ([preferred] if preferred in live else []) + sorted((s for s in live if s != preferred), key=cost)
        if not order:
            self.log.info("%s guard: closing move, no thread left to continue (%s)", self._case_id, reason)
            return close
        sid = order[0]
        self.log.info("%s guard: counter at their price on %s (%s)", self._case_id, sid, reason)
        return self._counter(case, threads, sid)

import logging

from test_kit import CASE

from arena_kit.agents.confident_boulware import ConfidentBoulwareAgent
from arena_kit.agents.confident_router import ConfidentRouterAgent
from arena_kit.agents.explorer import ExplorerAgent
from arena_kit.agents.rational import RationalAgent
from arena_kit.cost import must_haves_ok
from arena_kit.guard import GuardedAgent, fix_sheets, satisfy_must_haves

PPM = [300, 800, 1500, 2500]


def _case(must, negotiable, options, **extra):
    buyer = {**CASE["buyer"], "must_haves": must, "category_goal": "quality_first"}
    return {**CASE, "case_id": "case:G1", "negotiable": negotiable, "term_options": options, "buyer": buyer, **extra}


def _p11(**extra):
    return _case([{"field": "ppm_commitment", "op": "<=", "value": 1500}],
                 ["ppm_commitment", "chargeback_eur_per_complaint", "unit_price"],
                 {"ppm_commitment": PPM, "chargeback_eur_per_complaint": [0, 50, 100]}, **extra)


def _ev(sid="sup:A", terms=None, status="open", sent=1, price=47.0):
    terms = {"unit_price": price, "ppm_commitment": 6400} if terms is None else terms
    ev = [{"from": sid, "status": "open", "term_sheets": [{"term_sheet_id": "o0", "terms": terms}]}]
    for i in range(sent):
        ev += [{"from": "buyer", "term_sheets": [{"terms": {"unit_price": 40.0}}]},
               {"from": sid, "status": status, "term_sheets": [{"term_sheet_id": f"o{i + 1}", "terms": terms}]}]
    return ev


class Stub:
    def __init__(self, decision=None, error=False):
        self.decision, self.error = decision, error

    def decide(self, case, threads):
        if self.error:
            raise RuntimeError("boom")
        return self.decision


def _walk(sid="sup:A"):
    return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}


def _counter(sid="sup:A", price=40.0, ppm=2500):
    sheet = {"terms": {"unit_price": price, "ppm_commitment": ppm, "chargeback_eur_per_complaint": 0}}
    return {"supplier_id": sid, "message": {"subject": "s", "body": "b", "term_sheets": [sheet]}}


def _type(d):
    return (d["message"].get("action") or {}).get("type")


def test_satisfy_options():
    case = _p11()
    out = satisfy_must_haves(case, {"unit_price": 47.0, "ppm_commitment": 2500})
    assert out["ppm_commitment"] == 1500 and set(out) == set(case["negotiable"]) and must_haves_ok(case, out)
    case = _case([{"field": "lead_time_days", "op": "<=", "value": 42}], ["unit_price", "lead_time_days"],
                 {"lead_time_days": [28, 35, 42, 56]})
    assert satisfy_must_haves(case, {"unit_price": 40.0, "lead_time_days": 56})["lead_time_days"] == 42
    case = _case([{"field": "volume_per_year", "op": ">=", "value": 22230}], ["unit_price", "volume_per_year"],
                 {"volume_per_year": [16379, 19890, 23400]})
    out = satisfy_must_haves(case, {"unit_price": 40.0})
    assert out["volume_per_year"] == 23400 and must_haves_ok(case, out)


def test_satisfy_eq_noopts_and_nonnegotiable():
    case = _case([{"field": "payment_days", "op": "==", "value": 60}], ["unit_price", "payment_days"], 
                 {"payment_days": [30, 60]})
    assert satisfy_must_haves(case, {"unit_price": 40.0, "payment_days": 30})["payment_days"] == 60
    case = _case([{"field": "payment_days", "op": "<=", "value": 45}], ["unit_price", "payment_days"], {})
    assert satisfy_must_haves(case, {"unit_price": 40.0, "payment_days": 60})["payment_days"] == 45
    case = _case([{"field": "payment_days", "op": "<", "value": 45}], ["unit_price", "payment_days"], {})
    assert satisfy_must_haves(case, {"unit_price": 40.0, "payment_days": 60})["payment_days"] == 44
    case = _case([{"field": "payment_days", "op": "!=", "value": 30}], ["unit_price", "payment_days"], 
                 {"payment_days": [30, 60]})
    assert satisfy_must_haves(case, {"unit_price": 40.0, "payment_days": 30})["payment_days"] == 60
    case = _case([{"field": "incoterm", "op": "==", "value": "EXW"}], ["unit_price", "payment_days"], {})
    out = satisfy_must_haves(case, {"unit_price": 40.0, "payment_days": 30})
    assert out == {"unit_price": 40.0, "payment_days": 30} and not must_haves_ok(case, out)


def test_fix_sheets_dedup_and_cap():
    sheets = [{"terms": {"unit_price": 40.0, "ppm_commitment": 2500}}] * 2 + [
        {"terms": {"unit_price": p, "ppm_commitment": 2500}} for p in (39.0, 38.0, 37.0)]
    out = fix_sheets(_p11(), sheets)
    assert len(out) == 3 and all(s["terms"]["ppm_commitment"] == 1500 for s in out)


def test_counter_sheets_fixed():
    d = GuardedAgent(Stub(_counter(ppm=2500))).decide(_p11(), {"sup:A": _ev(sent=1)})
    assert d["message"]["term_sheets"][0]["terms"]["ppm_commitment"] == 1500


def test_walk_becomes_counter_twice_then_closing():
    case, g = _p11(), GuardedAgent(Stub(_walk()))
    th = {"sup:A": _ev(sent=1)}
    for _ in range(2):
        d = g.decide(case, th)
        sheet = d["message"]["term_sheets"][0]["terms"]
        assert sheet["unit_price"] == 47.0 and sheet["ppm_commitment"] == 1500
    assert _type(g.decide(case, th)) == "walk_away"  # closing_move: nothing safe


def test_exception_treated_as_walk():
    d = GuardedAgent(Stub(error=True)).decide(_p11(), {"sup:A": _ev(sent=1)})
    assert d["message"]["term_sheets"][0]["terms"]["ppm_commitment"] == 1500


def test_walk_with_safe_sheet_accepts():
    th = {"sup:A": _ev(terms={"unit_price": 38.0, "ppm_commitment": 800}, sent=1)}
    d = GuardedAgent(Stub(_walk())).decide(_p11(), th)
    assert d["message"]["action"] == {"type": "accept", "term_sheet_id": "o1"}


def test_final_offer_one_guard_counter_then_closing():
    case, g = _p11(), GuardedAgent(Stub(_walk()))
    th = {"sup:A": _ev(status="final_offer", sent=1)}
    assert g.decide(case, th)["message"]["term_sheets"][0]["terms"]["ppm_commitment"] == 1500
    assert _type(g.decide(case, th)) == "walk_away"


def test_last_move_rule():
    case = _p11(round_limit=2)  # one buyer message sent -> left == 1
    th = {"sup:A": _ev(sent=1)}
    d = GuardedAgent(Stub(_counter(price=40.0))).decide(case, th)
    assert d["message"]["term_sheets"][0]["terms"]["unit_price"] == 47.0  # their price, must-have fixed
    assert d["message"]["term_sheets"][0]["terms"]["ppm_commitment"] == 1500
    safe = {"sup:A": _ev(terms={"unit_price": 38.0, "ppm_commitment": 800}, sent=1)}
    assert _type(GuardedAgent(Stub(_counter(price=30.0))).decide(case, safe)) == "accept"
    done = {**case, "round_limit": 1}  # left == 0
    assert _type(GuardedAgent(Stub(_counter(price=30.0))).decide(done, safe)) == "accept"
    assert _type(GuardedAgent(Stub(_counter(price=30.0))).decide(done, th)) == "walk_away"  # nothing safe


def test_rfq_continues_on_other_thread():
    case = _p11(round_limit=10)
    th = {"sup:A": _ev("sup:A", status="final_offer", sent=1), "sup:B": _ev("sup:B", price=50.0, sent=1)}
    g = GuardedAgent(Stub(_walk("sup:A")))
    assert g.decide(case, th)["supplier_id"] == "sup:A"
    d = g.decide(case, th)  # A already tried once and is a final_offer
    assert d["supplier_id"] == "sup:B" and d["message"]["term_sheets"][0]["terms"]["ppm_commitment"] == 1500


def test_no_quote_asks_for_one():
    th = {"sup:A": [{"from": "sup:A", "status": "open", "term_sheets": [], "body": "hello"}]}
    d = GuardedAgent(Stub(_walk())).decide(_p11(), th)
    assert "term_sheets" not in d["message"] and "quote" in d["message"]["body"]


def test_new_case_resets_state():
    g = GuardedAgent(Stub(_walk()))
    th = {"sup:A": _ev(status="final_offer", sent=1)}
    g.decide(_p11(), th)
    assert _type(g.decide(_p11(), th)) == "walk_away"
    assert "term_sheets" in g.decide({**_p11(), "case_id": "case:G2"}, th)["message"]


def test_logs_intervention(caplog):
    with caplog.at_level(logging.INFO, logger="arena"):
        GuardedAgent(Stub(_walk())).decide(_p11(), {"sup:A": _ev(sent=1)})
    assert any("guard:" in r.getMessage() for r in caplog.records)


def test_p11_regression_all_delegates():
    case, th = _p11(), {"sup:A": _ev(sent=0)}
    th["sup:A"] = [th["sup:A"][0]]
    for agent in (GuardedAgent(ExplorerAgent()), GuardedAgent(RationalAgent()),
                  GuardedAgent(ConfidentBoulwareAgent()), ConfidentRouterAgent()):
        msg = agent.decide(case, th)["message"]
        assert msg.get("action") is None, agent
        assert msg["term_sheets"] and all(s["terms"]["ppm_commitment"] <= 1500 for s in msg["term_sheets"])


def test_router_delegates_are_guarded():
    from arena_kit.agents.confident_router import GUARDED
    from arena_kit.agents.router import FACTORIES

    expected = {**{n: type(f()) for n, f in FACTORIES.items()}, "confident_boulware": ConfidentBoulwareAgent}
    assert set(GUARDED) == set(expected)
    for name, make in GUARDED.items():
        g = make()
        assert isinstance(g, GuardedAgent) and type(g.delegate) is expected[name]

